'use client';

import React from 'react';
import { 
  ArrowUpLeft, 
  Sparkles, 
  Star, 
  Palette, 
  Video, 
  Camera, 
  PenTool, 
  Megaphone, 
  MapPin, 
  MessageSquare, 
  BarChart3, 
  Share2, 
  Zap, 
  Globe, 
  Users, 
  Layers,
  CheckCircle2
} from 'lucide-react';
import { packagesData } from '../../data/packages';
import { contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';

// دالة ذكية تحدد الأيقونة التخصصية ولونها بناءً على نص الميزة
const getSmartFeatureIcon = (text: string) => {
  if (text.includes('بوست') || text.includes('تصميم') || text.includes('Highlights')) {
    return <Palette className="w-4 h-4 text-cyan-400" />;
  }
  if (text.includes('فيديو')) {
    return <Video className="w-4 h-4 text-sky-400" />;
  }
  if (text.includes('تصوير') || text.includes('جلسات')) {
    return <Camera className="w-4 h-4 text-purple-400" />;
  }
  if (text.includes('محتوى') || text.includes('كتابة')) {
    return <PenTool className="w-4 h-4 text-amber-400" />;
  }
  if (text.includes('إعلان') || text.includes('حملات')) {
    return <Megaphone className="w-4 h-4 text-pink-400" />;
  }
  if (text.includes('قوقل') || text.includes('ماب')) {
    return <MapPin className="w-4 h-4 text-emerald-400" />;
  }
  if (text.includes('واتساب')) {
    return <MessageSquare className="w-4 h-4 text-emerald-400" />;
  }
  if (text.includes('تقرير') || text.includes('تحليل') || text.includes('تحليلات') || text.includes('الأداء')) {
    return <BarChart3 className="w-4 h-4 text-blue-400" />;
  }
  if (text.includes('حسابات') || text.includes('تواصل')) {
    return <Share2 className="w-4 h-4 text-indigo-400" />;
  }
  if (text.includes('استراتيجية') || text.includes('هوية') || text.includes('أولوية')) {
    return <Zap className="w-4 h-4 text-yellow-400" />;
  }
  if (text.includes('مواقع') || text.includes('متجر')) {
    return <Globe className="w-4 h-4 text-teal-400" />;
  }
  if (text.includes('مؤثرين') || text.includes('بلوجرز')) {
    return <Users className="w-4 h-4 text-rose-400" />;
  }
  return <CheckCircle2 className="w-4 h-4 text-cyan-400" />;
};

export const PricingSection: React.FC = () => {
  const standardPackages = packagesData.filter((pkg) => !pkg.isCustomQuote);
  const elitePackage = packagesData.find((pkg) => pkg.isCustomQuote);

  return (
    <section id="packages" className="py-24 lg:py-32 relative overflow-hidden">
      
      {/* توهج خلفي محيطي للقسم */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[500px] bg-cyan-500/5 rounded-full blur-[140px] pointer-events-none -z-0"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        
        {/* رأس القسم */}
        <div className="text-center max-w-2xl mx-auto mb-20 space-y-4">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-[#141b36] border border-cyan-500/20 text-xs font-bold text-cyan-300 shadow-inner">
            <Sparkles className="w-3.5 h-3.5 text-cyan-400 animate-pulse" />
            <span>خطط واستثمارات النمو</span>
          </div>

          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-black text-white tracking-tight leading-tight">
            اختر الباقة المناسبة لمرحلة <span className="brand-gradient-text">نمو علامتك</span>
          </h2>
          <p className="text-slate-400 text-sm sm:text-base leading-relaxed">
            باقات تسويقية متكاملة مصممة لتلبية متطلبات الحضور الرقمي وصناعة الأثر في السوق السعودي.
          </p>
        </div>

        {/* شبكة الباقات الأساسية الثلاث الأولى */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-stretch mb-16">
          {standardPackages.map((pkg) => {
            const isPopular = pkg.isPopular;
            const whatsappUrl = createWhatsAppLink(
              contactInfo.defaultWhatsApp,
              `مرحباً NT Media Agency، أرغب بالاشتراك في باقة "${pkg.name} | ${pkg.enName}".`
            );

            return (
              <div
                key={pkg.id}
                className={`relative flex flex-col justify-between rounded-3xl p-8 sm:p-9 transition-all duration-500 backdrop-blur-2xl group ${
                  isPopular
                    ? 'bg-[#141c3a]/90 border-2 border-cyan-400/50 shadow-[0_20px_50px_rgba(34,211,238,0.2)] lg:-translate-y-3'
                    : 'bg-[#10162e]/75 border border-white/[0.09] shadow-[0_15px_35px_rgba(0,0,0,0.6)] hover:border-cyan-500/30 hover:-translate-y-1'
                }`}
              >
                {/* وسم الأكثر طلباً المتوهج على باقة التأثير */}
                {isPopular && (
                  <div className="absolute -top-4 left-1/2 -translate-x-1/2">
                    <div className="flex items-center gap-1.5 px-4 py-1.5 rounded-full brand-gradient text-white text-xs font-black shadow-[0_0_20px_rgba(34,211,238,0.5)] border border-white/20">
                      <Star className="w-3.5 h-3.5 fill-current text-white animate-spin-slow" />
                      <span>الأكثر طلباً واختياراً</span>
                    </div>
                  </div>
                )}

                <div>
                  {/* رأس الكرت */}
                  <div className="border-b border-white/10 pb-6 mb-7">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="text-2xl font-black text-white group-hover:text-cyan-300 transition-colors">
                        {pkg.name}
                      </h3>
                      <span className="text-xs font-mono font-bold tracking-widest text-slate-400 bg-white/5 px-2.5 py-1 rounded-md border border-white/10 uppercase">
                        {pkg.enName}
                      </span>
                    </div>
                    <p className="text-xs text-slate-400 min-h-[36px] leading-relaxed">
                      {pkg.description}
                    </p>
                    
                   
                  </div>

                  {/* قائمة الميزات مع الأيقونات التخصصية الفخمة */}
                  <ul className="space-y-3.5 mb-8">
                    {pkg.features.map((feature, idx) => (
                      <li key={idx} className="flex items-start gap-3 text-sm text-slate-200">
                        {/* كبسولة الأيقونة الزجاجية المجسمة */}
                        <div className="w-7 h-7 rounded-lg bg-white/[0.05] border border-white/10 flex items-center justify-center shrink-0 mt-0.5 shadow-inner group-hover:border-cyan-500/30 transition-colors">
                          {getSmartFeatureIcon(feature)}
                        </div>
                        <span className="leading-snug font-medium pt-0.5 text-slate-300">
                          {feature}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>

                {/* زر الإجراء داخل الكرت */}
                <div className="pt-2">
                  <a
                    href={whatsappUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block w-full"
                  >
                    <button
                      className={`w-full py-3.5 px-6 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-all duration-300 cursor-pointer ${
                        isPopular
                          ? 'brand-gradient text-white shadow-[0_0_25px_rgba(56,189,248,0.35)] hover:shadow-[0_0_35px_rgba(56,189,248,0.6)] hover:scale-[1.02] active:scale-[0.98]'
                          : 'bg-white/5 border border-white/10 text-white hover:bg-white/10 hover:border-cyan-400/40 hover:scale-[1.02] active:scale-[0.98]'
                      }`}
                    >
                      <span>{pkg.ctaText}</span>
                      <ArrowUpLeft className="w-4 h-4 text-cyan-400 group-hover:text-white transition-colors" />
                    </button>
                  </a>
                </div>

              </div>
            );
          })}
        </div>

        {/* كرت باقة النخبة VIP الملكية الأسطورية */}
        {elitePackage && (
          <div className="mt-8">
            <div className="relative rounded-3xl p-8 sm:p-12 bg-gradient-to-r from-[#0e1428] via-[#141b36] to-[#0e1428] border-2 border-indigo-500/30 shadow-[0_25px_60px_rgba(0,0,0,0.8),inset_0_1px_1px_rgba(255,255,255,0.2)] overflow-hidden">
              
              {/* توهج ضوئي داخلي لباقة النخبة */}
              <div className="absolute top-0 right-0 w-80 h-80 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none"></div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-center relative z-10">
                
                {/* التفاصيل والعنوان */}
                <div className="lg:col-span-5 space-y-5">
                  <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-indigo-500/15 border border-indigo-400/30 text-xs font-bold text-indigo-300">
                    <Sparkles className="w-3.5 h-3.5 text-amber-400" />
                    <span>الباقة الملكية المتكاملة</span>
                  </div>

                  <h3 className="text-3xl sm:text-4xl font-black text-white tracking-tight">
                    {elitePackage.name}{' '}
                    <span className="brand-gradient-text">({elitePackage.enName})</span>
                  </h3>

                  <p className="text-sm text-slate-300 leading-relaxed font-normal">
                    {elitePackage.description}
                  </p>
                    

                  <div className="pt-3">
                    <a
                      href={createWhatsAppLink(
                        contactInfo.defaultWhatsApp,
                        'مرحباً NT Media Agency، نود الاستفسار ومناقشة تفاصيل باقة النخبة VIP.'
                      )}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-block w-full sm:w-auto"
                    >
                      <button className="w-full sm:w-auto px-8 py-4 rounded-xl brand-gradient text-white font-extrabold text-sm shadow-[0_0_25px_rgba(56,189,248,0.4)] hover:shadow-[0_0_35px_rgba(56,189,248,0.6)] hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2.5 cursor-pointer">
                        <span>{elitePackage.ctaText}</span>
                        <ArrowUpLeft className="w-4 h-4 text-white" />
                      </button>
                    </a>
                  </div>
                </div>

                {/* شبكة الخدمات الخاصة بالباقة الملكية بأيقوناتها الملونة */}
                <div className="lg:col-span-7 bg-[#0b0f1f]/80 p-6 sm:p-8 rounded-2xl border border-white/[0.08] shadow-inner backdrop-blur-md">
                  <div className="flex items-center gap-2 mb-6">
                    <Layers className="w-4 h-4 text-cyan-400" />
                    <h4 className="text-xs font-bold uppercase tracking-wider text-slate-300">
                      تشمل باقة النخبة VIP ما يلي:
                    </h4>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {elitePackage.features.map((feature, idx) => (
                      <div key={idx} className="flex items-center gap-3 text-sm text-slate-200">
                        <div className="w-7 h-7 rounded-lg bg-white/[0.06] border border-white/10 flex items-center justify-center shrink-0">
                          {getSmartFeatureIcon(feature)}
                        </div>
                        <span className="font-medium text-slate-300">{feature}</span>
                      </div>
                    ))}
                  </div>
                </div>

              </div>
            </div>
          </div>
        )}

      </div>
    </section>
  );
};